import React from 'react';
import './Forum.css';

const Forum = () => {
    const forums = [
        {
            id: 1,
            name: "General Discussion",
            description: "Talk about anything and everything.",
            subForums: [
                { id: 11, name: "Introductions", description: "Introduce yourself to the community." },
                { id: 12, name: "Off-Topic", description: "Discuss non-related topics." },
            ],
        },
        {
            id: 2,
            name: "News",
            description: "Stay updated with the latest news.",
            subForums: [
                { id: 21, name: "Announcements", description: "Official announcements and updates." },
                { id: 22, name: "Community News", description: "News from the community." },
            ],
        },
        {
            id: 3,
            name: "Support",
            description: "Get help and support for your issues.",
            subForums: [
                { id: 31, name: "Technical Support", description: "Get help with technical issues." },
                { id: 32, name: "Billing Support", description: "Help with billing questions." },
            ],
        },
    ];

    return (
        <div className="forum-list">
            <h2>Forums</h2>
            <ul>
                {forums.map((forum) => (
                    <li key={forum.id} className="forum-item">
                        <h3>{forum.name}</h3>
                        <p>{forum.description}</p>
                        <ul className="subforum-list">
                            {forum.subForums.map((subForum) => (
                                <li key={subForum.id} className="subforum-item">
                                    <h4>{subForum.name}</h4>
                                    <p>{subForum.description}</p>
                                </li>
                            ))}
                        </ul>
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default Forum;
